import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import type { Session, SupabaseClient } from '@supabase/supabase-js';
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, BarChart3, CalendarDays, Check, CheckCheck, ChevronLeft, ChevronRight, Clock3, Copy, FolderKanban, LayoutDashboard, ListTodo, LogOut, MoreHorizontal, Pencil, Play, Plus, RefreshCw, Settings2, ShieldCheck, Square, Trash2, Users, X } from 'lucide-react';
import { createService } from '../shared/service';
import type { Membership, Project, Role, RunningTimer, Task, TimeEntry, Workspace } from '../shared/types';
import { AuthShell, ConnectedApps, type RuntimeConfig } from './auth';
import { Logo } from './Logo';
import { Dialog, Empty, Field, FormActions, Notice, Spinner, TaskAssigneeSelect } from './components';
import { addDays, dateInZone, downloadCsv, entriesCsv, errorMessage, initials, longDate, minutesLabel, roleNames, shortDate, statusNames, validRange, weekFor } from './helpers';

type Service = ReturnType<typeof createService>;
type Nav = 'overview'|'projects'|'tasks'|'time'|'reports'|'team'|'settings';
const navigation: { id: Nav; name: string; icon: typeof Clock3 }[] = [{ id: 'overview', name: 'Übersicht', icon: LayoutDashboard }, { id: 'projects', name: 'Projekte', icon: FolderKanban }, { id: 'tasks', name: 'Aufgaben', icon: ListTodo }, { id: 'time', name: 'Zeiten', icon: Clock3 }, { id: 'reports', name: 'Auswertung', icon: BarChart3 }, { id: 'team', name: 'Team', icon: Users }, { id: 'settings', name: 'Einstellungen', icon: Settings2 }];
type Dataset = { projects: Project[]; tasks: Task[]; members: Membership[]; entries: TimeEntry[]; timer: RunningTimer | null };
type Modal = { type: 'project'; item?: Project } | { type: 'task'; item?: Task } | { type: 'entry'; item?: TimeEntry } | { type: 'invite' } | { type: 'confirm'; title: string; text: string; label: string; action: () => Promise<unknown> };
function Status({ value }: { value: keyof typeof statusNames }) { return <span className={`badge badge-${value}`}>{statusNames[value]}</span>; }
function ProjectMark({ project }: { project?: Project }) { return <span className="project-mark" style={{ backgroundColor: project?.color || '#641dff' }} aria-hidden="true">{project?.code.slice(0, 2) || '↗'}</span>; }
function sum(entries: TimeEntry[]) { return entries.reduce((n, entry) => n + entry.minutes, 0); }

export function WorkspaceApp({ client, session, config, signOut }: { client: SupabaseClient; session: Session; config: RuntimeConfig; signOut: () => Promise<void> }) {
  const service = useMemo(() => createService(client), [client]); const [workspaces, setWorkspaces] = useState<Workspace[]>([]); const [selected, setSelected] = useState(''); const [ready, setReady] = useState(false); const [error, setError] = useState(''); const [creating, setCreating] = useState(false); const [attempt, setAttempt] = useState(0);
  useEffect(() => { let alive = true; setReady(false); setError(''); (async () => { try { await service.acceptInvitations(); const list = await service.listWorkspaces(); if (!alive) return; setWorkspaces(list); setSelected(old => list.some(w => w.id === old) ? old : list[0]?.id || ''); } catch (e) { if (alive) setError(errorMessage(e)); } finally { if (alive) setReady(true); } })(); return () => { alive = false; }; }, [service, attempt]);
  const workspace = workspaces.find(w => w.id === selected);
  const created = (w: Workspace) => { setWorkspaces(old => [...old, w]); setSelected(w.id); setCreating(false); };
  if (!ready) return <div className="boot"><Spinner label="Deine Workspaces werden geladen …"/></div>;
  if (error) return <AuthShell><section className="auth-card"><h2>Fast da.</h2><Notice>{error}</Notice><button className="button primary" onClick={() => setAttempt(n => n + 1)}><RefreshCw size={17}/> Erneut versuchen</button><button className="text-button block" onClick={() => void signOut()}>Abmelden</button></section></AuthShell>;
  if (!workspace) return <AuthShell caption="Ein Team. Ein gemeinsamer Flow."><WorkspaceForm service={service} onCreated={created} onCancel={() => void signOut()} first/></AuthShell>;
  return <><WorkspaceView key={`${session.user.id}:${workspace.id}`} service={service} client={client} session={session} workspace={workspace} workspaces={workspaces} onWorkspace={setSelected} onCreateWorkspace={() => setCreating(true)} config={config} signOut={signOut}/>{creating && <Dialog title="Neuer Workspace" onClose={() => setCreating(false)}><WorkspaceForm service={service} onCreated={created} onCancel={() => setCreating(false)}/></Dialog>}</>;
}
function WorkspaceForm({ service, onCreated, onCancel, first = false }: { service: Service; onCreated: (w: Workspace) => void; onCancel: () => void; first?: boolean }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setBusy(true); setError(''); const f = new FormData(e.currentTarget); try { const timezone = String(f.get('timezone')).trim(); try { new Intl.DateTimeFormat('de-DE', { timeZone: timezone }); } catch { throw new Error('Bitte gib eine gültige IANA-Zeitzone ein, zum Beispiel Europe/Berlin.'); } const w = await service.createWorkspace({ name: String(f.get('name')).trim(), timezone, currency: String(f.get('currency')).toUpperCase() }); onCreated(w); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <section className={first ? 'auth-card' : ''}>{first && <><p className="eyebrow purple">DEIN ERSTER WORKSPACE</p><h2>Hier beginnt<br/>euer nächstes Projekt.</h2><p className="muted">Gib eurem gemeinsamen Arbeitsort einen Namen. Projekte und Team kommen gleich dazu.</p></>}{error && <Notice>{error}</Notice>}<form className="form-stack" onSubmit={submit}><Field label="Workspace-Name"><input name="name" required minLength={1} maxLength={100} placeholder="Zum Beispiel: Studio Nord" autoComplete="organization"/></Field><Field label="Zeitzone" hint="Timer werden an Mitternacht in dieser Zeitzone aufgeteilt."><input name="timezone" required defaultValue={Intl.DateTimeFormat().resolvedOptions().timeZone || 'Europe/Berlin'} list="timezones"/><datalist id="timezones">{['Europe/Berlin','Europe/Vienna','Europe/Zurich','Europe/London','America/New_York','America/Los_Angeles','Asia/Tokyo','UTC'].map(t => <option key={t}>{t}</option>)}</datalist></Field><Field label="Währung"><select name="currency" defaultValue="EUR"><option value="EUR">EUR · Euro</option><option value="CHF">CHF · Schweizer Franken</option><option value="USD">USD · US-Dollar</option><option value="GBP">GBP · Pfund Sterling</option></select></Field>{first ? <><button className="button primary full" disabled={busy}>{busy ? 'Wird angelegt …' : 'Workspace anlegen'}<ArrowRight size={17}/></button><button className="text-button" disabled={busy} type="button" onClick={onCancel}>Abmelden</button><p className="tiny muted">Du wurdest eingeladen? Melde dich mit der eingeladenen, bestätigten E-Mail-Adresse an. Einladungen werden beim Anmelden automatisch angenommen.</p></> : <FormActions busy={busy} onClose={onCancel} label="Workspace anlegen"/>}</form></section>;
}

function WorkspaceView({ service, client, session, workspace, workspaces, onWorkspace, onCreateWorkspace, config, signOut }: { service: Service; client: SupabaseClient; session: Session; workspace: Workspace; workspaces: Workspace[]; onWorkspace: (id: string) => void; onCreateWorkspace: () => void; config: RuntimeConfig; signOut: () => Promise<void> }) {
  const [nav, setNav] = useState<Nav>('overview'); const [range, setRange] = useState(() => weekFor(dateInZone(workspace.timezone))); const [data, setData] = useState<Dataset | null>(null); const [loadedRange, setLoadedRange] = useState(''); const [loading, setLoading] = useState(true); const [loadError, setLoadError] = useState(''); const [notice, setNotice] = useState<{ message: string; error: boolean } | null>(null); const [busy, setBusy] = useState(false); const [modal, setModal] = useState<Modal | null>(null); const generation = useRef(0); const mounted = useRef(true);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; generation.current++; }; }, []);
  const load = useCallback(async () => { const request = ++generation.current; setLoading(true); setLoadError(''); try { const [projects, tasks, members, entries, timer] = await Promise.all([service.listProjects(workspace.id), service.listTasks(workspace.id), service.getMemberships(workspace.id), service.listEntries(workspace.id, range.from, range.to), service.getTimer()]); if (mounted.current && request === generation.current) { setData({ projects, tasks, members, entries, timer }); setLoadedRange(`${range.from}:${range.to}`); } } catch (e) { if (mounted.current && request === generation.current) { setData(null); setLoadError(errorMessage(e)); } } finally { if (mounted.current && request === generation.current) setLoading(false); } }, [service, workspace.id, range.from, range.to]);
  useEffect(() => { void load(); }, [load]);
  // Returning to this tab refreshes server-owned timers and membership changes.
  useEffect(() => { const onVisible = () => { if (document.visibilityState === 'visible') void load(); }; document.addEventListener('visibilitychange', onVisible); return () => document.removeEventListener('visibilitychange', onVisible); }, [load]);
  const self = data?.members.find(m => m.user_id === session.user.id); const role = self?.role ?? 'member'; const manager = role === 'owner' || role === 'manager'; const name = self?.display_name || session.user.email?.split('@')[0] || 'du';
  async function run(action: () => Promise<unknown>, success?: string) { if (busy) return false; setBusy(true); setNotice(null); try { await action(); if (!mounted.current) return true; setModal(null); await load(); if (mounted.current && success) setNotice({ message: success, error: false }); return true; } catch (e) { if (mounted.current) setNotice({ message: errorMessage(e), error: true }); return false; } finally { if (mounted.current) setBusy(false); } }
  function go(next: Nav) { setNav(next); setNotice(null); document.getElementById('main-title')?.focus(); }
  const titles: Record<Nav, { title: string; subtitle: string }> = { overview: { title: `Guten Flow, ${name.split(' ')[0]}.`, subtitle: 'Ein klarer Blick auf deine Arbeit.' }, projects: { title: 'Raum für gute Projekte.', subtitle: 'Vom ersten Gedanken bis zum letzten Feinschliff.' }, tasks: { title: 'Ein Schritt nach dem anderen.', subtitle: 'Was ansteht. Was läuft. Was geschafft ist.' }, time: { title: 'Deine Zeit zählt.', subtitle: 'Erfassen, prüfen und mit gutem Gefühl einreichen.' }, reports: { title: 'Der Überblick fürs Ganze.', subtitle: 'Arbeitszeit und Projektbudgets im gewählten Zeitraum.' }, team: { title: 'Gemeinsam kommt ihr weiter.', subtitle: 'Menschen, Rollen und euer gemeinsamer Workspace.' }, settings: { title: 'Alles gut eingestellt.', subtitle: 'Dein Account, dein Workspace und deine Verbindungen.' } };
  return <div className="app-shell"><a className="skip-link" href="#main">Zum Inhalt</a><aside className="sidebar"><Logo/><div className="workspace-switch"><label htmlFor="workspace-select">WORKSPACE</label><div className="workspace-select-row"><span className="workspace-avatar">{initials(workspace.name)}</span><select id="workspace-select" value={workspace.id} onChange={e => onWorkspace(e.target.value)} aria-label="Workspace wechseln">{workspaces.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></div><button className="text-button tiny" onClick={onCreateWorkspace}><Plus size={13}/><span>Neuer Workspace</span></button></div><nav aria-label="Hauptnavigation">{navigation.map(item => <button key={item.id} className={`nav-item ${nav === item.id ? 'active' : ''}`} onClick={() => go(item.id)} aria-current={nav === item.id ? 'page' : undefined}><item.icon size={19}/><span>{item.name}</span>{item.id === 'time' && !!data?.entries.filter(e => e.status === 'submitted').length && manager && <span className="nav-count">{data.entries.filter(e => e.status === 'submitted').length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="small-manifesto">Good work.<br/><span>Great flow.</span><ArrowUpRight size={27}/></div><div className="profile"><span className="avatar">{initials(name)}</span><div><strong>{name}</strong><small>{roleNames[role]}</small></div><button className="icon-button" aria-label="Abmelden" title="Abmelden" onClick={() => void signOut()}><LogOut size={17}/></button></div></div></aside><div className="app-main"><header className="topbar"><span className="breadcrumb">{workspace.name}<span>/</span><strong>{navigation.find(n => n.id === nav)?.name}</strong></span><div className="topbar-right"><span className="timezone"><span className="status-dot"/>{workspace.timezone}</span><button className="icon-button" aria-label="Daten aktualisieren" disabled={loading || busy} onClick={() => void load()}><RefreshCw size={17} className={loading ? 'spin' : ''}/></button><span className="avatar small-avatar" title={session.user.email}>{initials(name)}</span></div></header><main id="main" className="main-content"><div className="page-heading"><div><p className="eyebrow">{nav === 'overview' ? 'LET’S MAKE IT COUNT' : 'VAVE.LOG / ' + navigation.find(n => n.id === nav)?.name.toUpperCase()}</p><h1 id="main-title" tabIndex={-1}>{titles[nav].title}</h1><p>{titles[nav].subtitle}</p></div><div className="heading-actions">{(nav === 'overview' || nav === 'time') && <button className="button primary" disabled={!data?.projects.some(p => p.status === 'active') || loading} onClick={() => setModal({ type: 'entry' })}><Plus size={17}/> Zeit erfassen</button>}{nav === 'projects' && manager && <button className="button primary" onClick={() => setModal({ type: 'project' })}><Plus size={17}/> Neues Projekt</button>}{nav === 'tasks' && <button className="button primary" disabled={!data?.projects.some(p => p.status === 'active') || loading} onClick={() => setModal({ type: 'task' })}><Plus size={17}/> Neue Aufgabe</button>}{nav === 'team' && role === 'owner' && <button className="button primary" onClick={() => setModal({ type: 'invite' })}><Plus size={17}/> Person einladen</button>}</div></div>{notice && <div className="notice-row"><Notice kind={notice.error ? 'error' : 'success'}>{notice.message}</Notice><button className="icon-button" aria-label="Hinweis schließen" onClick={() => setNotice(null)}><X size={16}/></button></div>}{['overview','projects','time','reports'].includes(nav) && <RangePicker key={`${range.from}:${range.to}`} range={range} onChange={setRange} today={dateInZone(workspace.timezone)} busy={busy}/>}{loading && (!data || loadedRange !== `${range.from}:${range.to}`) ? <Spinner label="Workspace wird aktualisiert …"/> : loadError ? <div className="panel"><Notice>{loadError}</Notice><button className="button secondary" onClick={() => void load()}>Erneut versuchen</button></div> : data && <>{nav === 'overview' && <Overview data={data} workspace={workspace} userId={session.user.id} range={range} manager={manager} setModal={setModal} go={go} service={service} run={run} busy={busy} workspaces={workspaces}/>} {nav === 'projects' && <Projects data={data} manager={manager} setModal={setModal} range={range}/>} {nav === 'tasks' && <Tasks data={data} userId={session.user.id} setModal={setModal} service={service} run={run} busy={busy}/>} {nav === 'time' && <Times data={data} userId={session.user.id} manager={manager} range={range} workspace={workspace} setModal={setModal} service={service} run={run} busy={busy}/>} {nav === 'reports' && <Reports data={data} range={range} manager={manager}/>} {nav === 'team' && <Team data={data} userId={session.user.id} role={role} service={service} run={run} busy={busy} workspace={workspace} setModal={setModal}/>} {nav === 'settings' && <Settings workspace={workspace} self={self} client={client} config={config} signOut={signOut}/>}</>}<footer className="app-footer"><span>VAVE.LOG <span className="footer-dot">●</span> SPACE FOR GOOD WORK</span><span>{workspace.name}</span></footer></main></div>{modal && data && <Editor key={modal.type === 'project' || modal.type === 'task' || modal.type === 'entry' ? `${modal.type}:${modal.item?.id || 'new'}` : modal.type} modal={modal} data={data} workspace={workspace} service={service} run={run} busy={busy} onClose={() => setModal(null)} appUrl={config.appUrl} errorDetail={notice?.error ? notice.message : undefined}/>}</div>;
}

function RangePicker({ range, onChange, today, busy }: { range: { from: string; to: string }; onChange: (r: { from: string; to: string }) => void; today: string; busy: boolean }) {
  const [from, setFrom] = useState(range.from); const [to, setTo] = useState(range.to); const [expanded, setExpanded] = useState(false); const [error, setError] = useState('');
  const days = Math.round((Date.parse(range.to) - Date.parse(range.from)) / 86400000) + 1;
  return <div className="range-toolbar"><div className="range-controls"><button className="icon-button" aria-label="Vorheriger Zeitraum" disabled={busy} onClick={() => onChange({ from: addDays(range.from, -days), to: addDays(range.to, -days) })}><ChevronLeft size={17}/></button><button className="range-label" aria-expanded={expanded} onClick={() => setExpanded(!expanded)}><CalendarDays size={16}/>{shortDate(range.from)} – {shortDate(range.to)}<span className="muted">{range.to.slice(0, 4)}</span></button><button className="icon-button" aria-label="Nächster Zeitraum" disabled={busy} onClick={() => onChange({ from: addDays(range.from, days), to: addDays(range.to, days) })}><ChevronRight size={17}/></button><button className="text-button tiny" disabled={busy} onClick={() => onChange(weekFor(today))}>Diese Woche</button></div><span className="range-hint">Alle Auswertungen beziehen sich auf diesen Zeitraum.</span>{expanded && <form className="range-form" onSubmit={e => { e.preventDefault(); if (!validRange(from, to)) { setError('Wähle einen gültigen Zeitraum von maximal 366 Tagen.'); return; } onChange({ from, to }); setExpanded(false); }}><Field label="Von"><input type="date" min="2000-01-01" max="2100-12-31" required value={from} onChange={e => setFrom(e.target.value)}/></Field><Field label="Bis"><input type="date" min="2000-01-01" max="2100-12-31" required value={to} onChange={e => setTo(e.target.value)}/></Field><button className="button primary small" disabled={busy}>Anwenden</button>{error && <Notice>{error}</Notice>}</form>}</div>;
}

type Run = (action: () => Promise<unknown>, success?: string) => Promise<boolean>;
function Overview({ data, workspace, userId, range, manager, setModal, go, service, run, busy, workspaces }: { data: Dataset; workspace: Workspace; userId: string; range: { from: string; to: string }; manager: boolean; setModal: (m: Modal) => void; go: (n: Nav) => void; service: Service; run: Run; busy: boolean; workspaces: Workspace[] }) {
  const own = data.entries.filter(e => e.user_id === userId); const total = sum(own); const billable = sum(own.filter(e => e.billable)); const open = data.tasks.filter(t => t.status !== 'done' && t.assignee_id === userId); const drafts = own.filter(e => e.status === 'draft'); const days = Math.round((Date.parse(range.to) - Date.parse(range.from)) / 86400000) + 1; const bucketSize = Math.ceil(days / 7); const bars = Array.from({ length: Math.ceil(days / bucketSize) }, (_, i) => { const date = addDays(range.from, i * bucketSize); const end = addDays(date, bucketSize - 1); return { date, value: sum(own.filter(e => e.work_date >= date && e.work_date <= end)) }; }); const max = Math.max(60, ...bars.map(b => b.value));
  return <><div className="metric-grid"><Metric label="Deine erfasste Zeit" value={minutesLabel(total)} sub={`${own.length} Zeiteinträge im Zeitraum`} icon={<Clock3 size={19}/>} featured/><Metric label="Davon abrechenbar" value={minutesLabel(billable)} sub={total ? `${Math.round(billable / total * 100)} % deiner erfassten Zeit` : 'Bereit für dein erstes Projekt'} icon={<Activity size={19}/>}/><Metric label="Bereit zum Einreichen" value={minutesLabel(sum(drafts))} sub={`${drafts.length} offene Entwürfe`} icon={<CheckCheck size={19}/>}/><Metric label="Deine offenen Aufgaben" value={String(open.length).padStart(2, '0')} sub="Über alle Projekte hinweg" icon={<ListTodo size={19}/>}/></div><div className="overview-grid"><section className="panel time-chart"><div className="panel-heading"><div><p className="eyebrow">DEIN RHYTHMUS</p><h2>Zeit, die etwas bewegt.</h2></div><span className="tiny muted">{bucketSize === 1 ? 'Pro Tag' : `Je ${bucketSize} Tage`}</span></div><div className="chart" role="img" aria-label={bars.map(b => `${longDate(b.date)}: ${minutesLabel(b.value)}`).join('; ')}>{bars.map(b => <div className="chart-column" key={b.date}><strong>{b.value ? minutesLabel(b.value).replace(' h','') : '–'}</strong><div className="chart-bar-track"><div className={`chart-bar ${b.date === dateInZone(workspace.timezone) ? 'today' : ''}`} style={{ height: `${Math.max(b.value ? 3 : 0, b.value / max * 100)}%` }}/></div><span>{bucketSize === 1 ? new Intl.DateTimeFormat('de-DE', { weekday: 'short', timeZone: 'UTC' }).format(new Date(`${b.date}T12:00:00Z`)) : shortDate(b.date)}</span></div>)}</div><div className="chart-footer"><span><span className="chart-key"/> Deine erfasste Arbeitszeit</span><button className="text-button tiny" onClick={() => go('time')}>Alle Zeiten <ArrowRight size={14}/></button></div></section><TimerPanel data={data} workspace={workspace} workspaces={workspaces} service={service} run={run} busy={busy} setModal={setModal}/><section className="panel"><div className="panel-heading"><div><p className="eyebrow">ZULETZT ERFASST</p><h2>Deine Arbeit im Rückblick.</h2></div><button className="icon-button" aria-label="Alle Zeiten öffnen" onClick={() => go('time')}><ArrowUpRight size={20}/></button></div>{own.length === 0 ? <Empty title="Noch ganz viel möglich." text="Starte den Timer oder erfasse deine erste Arbeitszeit." action={<button className="text-button" disabled={!data.projects.some(p => p.status === 'active')} onClick={() => setModal({ type: 'entry' })}>Zeit erfassen <ArrowRight size={15}/></button>}/> : <div className="recent-entries">{[...own].sort((a,b) => b.work_date.localeCompare(a.work_date) || b.created_at.localeCompare(a.created_at)).slice(0,4).map(entry => { const p = data.projects.find(p => p.id === entry.project_id); return <div className="recent-entry" key={entry.id}><ProjectMark project={p}/><div className="entry-info"><strong>{entry.note || p?.name || 'Arbeitszeit'}</strong><small>{p?.name} <span>·</span> {shortDate(entry.work_date)}</small></div><div className="entry-end"><strong>{minutesLabel(entry.minutes)}</strong><Status value={entry.status}/></div></div>; })}</div>}</section><section className="panel next-tasks"><div className="panel-heading"><div><p className="eyebrow">DEIN NÄCHSTER SCHRITT</p><h2>Was steht an?</h2></div><span className="count-circle">{open.length}</span></div>{open.length === 0 ? <Empty title="Freier Kopf. Freie Bahn." text="Dir sind gerade keine offenen Aufgaben zugewiesen." action={<button className="text-button" onClick={() => go('tasks')}>Zum Aufgabenboard <ArrowRight size={15}/></button>}/> : open.slice().sort((a,b) => (a.due_date || '9999').localeCompare(b.due_date || '9999')).slice(0,4).map(task => <button className="next-task" key={task.id} onClick={() => setModal({ type: 'task', item: task })}><span className="task-check"/><div><strong>{task.title}</strong><small>{data.projects.find(p => p.id === task.project_id)?.name}</small></div>{task.due_date && <span className={`due-date ${task.due_date < dateInZone(workspace.timezone) ? 'overdue' : ''}`}>{shortDate(task.due_date)}</span>}</button>)}</section></div>{data.projects.length === 0 && <div className="start-strip"><div><strong>Alles beginnt mit einem Projekt.</strong><p>{manager ? 'Lege dein erstes Projekt an. Danach könnt ihr Aufgaben und Zeiten hinzufügen.' : 'Bitte die Workspace-Leitung, ein erstes Projekt anzulegen.'}</p></div>{manager && <button className="button secondary" onClick={() => setModal({ type: 'project' })}>Projekt anlegen <ArrowUpRight size={17}/></button>}</div>}</>;
}
function Metric({ label, value, sub, icon, featured }: { label: string; value: string; sub: string; icon: ReactNode; featured?: boolean }) { return <section className={`metric ${featured ? 'featured' : ''}`}><div><span>{label}</span>{icon}</div><strong className="metric-value">{value}</strong><p>{sub}</p></section>; }
function TimerPanel({ data, workspace, workspaces, service, run, busy, setModal }: { data: Dataset; workspace: Workspace; workspaces: Workspace[]; service: Service; run: Run; busy: boolean; setModal: (m: Modal) => void }) {
  const [project, setProject] = useState(data.projects.find(p => p.status === 'active')?.id || ''); const [note, setNote] = useState(''); const [billable, setBillable] = useState(true); const [now, setNow] = useState(Date.now());
  useEffect(() => { if (!data.projects.some(p => p.id === project && p.status === 'active')) setProject(data.projects.find(p => p.status === 'active')?.id || ''); }, [data.projects, project]);
  useEffect(() => { if (!data.timer) return; const interval = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(interval); }, [data.timer]);
  const elapsed = data.timer ? Math.max(0, Math.floor((now - Date.parse(data.timer.started_at)) / 1000)) : 0; const tooLong = elapsed > 24 * 3600; const clock = `${String(Math.floor(elapsed / 3600)).padStart(2,'0')}:${String(Math.floor(elapsed / 60) % 60).padStart(2,'0')}:${String(elapsed % 60).padStart(2,'0')}`;
  return <section className={`timer-panel ${data.timer ? 'running' : ''}`}><div className="timer-heading"><span className="eyebrow">{data.timer ? 'DU BIST IM FLOW' : 'EINS NACH DEM ANDEREN'}</span><span className={data.timer ? 'live-dot' : 'timer-star'}>{!data.timer && '✳'}</span></div><h2>{data.timer ? 'Deine Zeit läuft.' : 'Fokus an. Timer los.'}</h2><div className="timer-clock" aria-label={`Timer: ${clock}`}>{clock}</div>{data.timer ? <><div className="running-info"><strong>{data.projects.find(p => p.id === data.timer!.project_id)?.name || 'Projekt in anderem Workspace'}</strong><p>{data.timer.note || 'Konzentriert bei der Sache.'}</p>{data.timer.workspace_id !== workspace.id && <small>Workspace: {workspaces.find(w => w.id === data.timer!.workspace_id)?.name || 'anderer Workspace'}</small>}</div>{tooLong && <Notice kind="info">Dieser Timer läuft länger als 24 Stunden. Verwirf ihn und erfasse die korrekte Zeit manuell.</Notice>}<button className="button timer-stop full" disabled={busy || elapsed < 60 || tooLong} onClick={() => void run(() => service.stopTimer(data.timer!.id), 'Timer gestoppt. Deine Zeit wurde gespeichert.')}><Square size={15} fill="currentColor"/>{elapsed < 60 ? 'Speichern ab 1 Minute' : 'Stoppen & speichern'}</button><button className="text-button timer-discard" disabled={busy} onClick={() => setModal({ type: 'confirm', title: 'Timer verwerfen?', text: 'Die laufende Zeit wird nicht als Arbeitszeit gespeichert. Du kannst sie anschließend manuell erfassen.', label: 'Timer verwerfen', action: () => service.discardTimer(data.timer!.id) })}>Timer verwerfen</button></> : <form onSubmit={e => { e.preventDefault(); void run(() => service.startTimer({ workspace_id: workspace.id, project_id: project, note: note.trim(), billable }), 'Timer gestartet. Guter Flow!'); }}><Field label="Projekt"><select value={project} required onChange={e => setProject(e.target.value)}><option value="" disabled>Projekt auswählen</option>{data.projects.filter(p => p.status === 'active').map(p => <option key={p.id} value={p.id}>{p.code} · {p.name}</option>)}</select></Field><Field label="Woran arbeitest du?"><input maxLength={2000} value={note} onChange={e => setNote(e.target.value)} placeholder="Zum Beispiel: Konzept & Gestaltung"/></Field><label className="checkbox-field"><input type="checkbox" checked={billable} onChange={e => setBillable(e.target.checked)}/> Abrechenbar</label><button className="button timer-start full" disabled={busy || !project}><Play size={16} fill="currentColor"/> Timer starten</button></form>}</section>;
}
function Projects({ data, manager, setModal, range }: { data: Dataset; manager: boolean; setModal: (m: Modal) => void; range: { from: string; to: string } }) {
  const [filter, setFilter] = useState('active'); const [search, setSearch] = useState(''); const list = data.projects.filter(p => (filter === 'all' || p.status === filter) && `${p.code} ${p.name} ${p.client}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
  return <><div className="list-toolbar"><div className="segmented" aria-label="Projektstatus">{[['active','Aktiv'],['paused','Pausiert'],['archived','Archiviert'],['all','Alle']].map(([value,label]) => <button key={value} className={filter === value ? 'selected' : ''} aria-pressed={filter === value} onClick={() => setFilter(value)}>{label}</button>)}</div><label className="search-field"><span className="sr-only">Projekte durchsuchen</span><input type="search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Projekt oder Kunde suchen …"/></label></div>{list.length === 0 ? <section className="panel"><Empty title={data.projects.length ? 'Hier ist gerade Platz.' : 'Gute Ideen brauchen ein Zuhause.'} text={data.projects.length ? 'Für diese Auswahl wurden keine Projekte gefunden.' : manager ? 'Lege dein erstes Projekt an und bring dein Team zusammen.' : 'Eure Workspace-Leitung kann das erste Projekt anlegen.'} action={manager && !data.projects.length ? <button className="button primary" onClick={() => setModal({ type: 'project' })}><Plus size={16}/> Erstes Projekt anlegen</button> : undefined}/></section> : <div className="project-grid">{list.map(project => { const used = sum(data.entries.filter(e => e.project_id === project.id)); const tasks = data.tasks.filter(t => t.project_id === project.id); return <article className="project-card" key={project.id}><div className="project-card-top"><ProjectMark project={project}/><Status value={project.status}/>{manager && <button className="icon-button" aria-label={`${project.name} bearbeiten`} onClick={() => setModal({ type: 'project', item: project })}><Pencil size={16}/></button>}</div><p className="project-code">{project.code}</p><h2>{project.name}</h2><p className="muted project-client">{project.client || 'Kein Kunde hinterlegt'}</p><div className="project-budget"><div><strong>{minutesLabel(used)}</strong><span>{project.budget_minutes ? `Budget: ${minutesLabel(project.budget_minutes)}` : 'Ohne Zeitbudget'}</span></div><div className="progress-track"><div className={project.budget_minutes && used > project.budget_minutes ? 'over-budget' : ''} style={{ width: `${project.budget_minutes ? Math.min(100, used / project.budget_minutes * 100) : 0}%`, backgroundColor: project.color }}/></div><small>Erfasst {shortDate(range.from)}–{shortDate(range.to)} · {manager ? 'Team' : 'deine Zeit'}</small></div><div className="project-card-footer"><span><ListTodo size={15}/>{tasks.filter(t => t.status === 'done').length}/{tasks.length} Aufgaben</span><span>{project.budget_minutes && used > project.budget_minutes ? 'Über Gesamtbudget' : 'MAKE IT HAPPEN ↗'}</span></div></article>; })}</div>}</>;
}
function Tasks({ data, userId, setModal, service, run, busy }: { data: Dataset; userId: string; setModal: (m: Modal) => void; service: Service; run: Run; busy: boolean }) {
  const [project, setProject] = useState('all'); const [mine, setMine] = useState(false); const filtered = data.tasks.filter(t => (project === 'all' || t.project_id === project) && (!mine || t.assignee_id === userId));
  function move(task: Task, status: Task['status']) { return run(() => service.saveTask({ id: task.id, workspace_id: task.workspace_id, project_id: task.project_id, title: task.title, status, assignee_id: task.assignee_id, due_date: task.due_date }), 'Aufgabenstatus aktualisiert.'); }
  return <><div className="list-toolbar"><label className="inline-field"><span>Projekt</span><select value={project} onChange={e => setProject(e.target.value)}><option value="all">Alle Projekte</option>{data.projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className="checkbox-field"><input type="checkbox" checked={mine} onChange={e => setMine(e.target.checked)}/> Nur meine Aufgaben</label></div><div className="task-board">{(['todo','doing','done'] as const).map(status => <section className={`task-column column-${status}`} key={status}><div className="task-column-title"><span className="column-dot"/><h2>{statusNames[status]}</h2><span>{filtered.filter(t => t.status === status).length}</span></div>{filtered.filter(t => t.status === status).map(task => { const p = data.projects.find(p => p.id === task.project_id); const person = data.members.find(m => m.user_id === task.assignee_id); return <article className="task-card" key={task.id}><div className="task-project"><span style={{ backgroundColor: p?.color }}/>{p?.code || 'Projekt'}<button className="icon-button" aria-label={`Aufgabe ${task.title} bearbeiten`} onClick={() => setModal({ type: 'task', item: task })}><MoreHorizontal size={17}/></button></div><button className="task-title" onClick={() => setModal({ type: 'task', item: task })}>{task.title}</button><div className="task-meta"><span>{task.due_date ? <><CalendarDays size={13}/>{shortDate(task.due_date)}</> : 'Ohne Termin'}</span>{person ? <span className="avatar tiny-avatar" title={person.display_name || person.email}>{initials(person.display_name || person.email)}</span> : <span className="tiny muted">Nicht zugewiesen</span>}</div><label className="task-status-field"><span className="sr-only">Status für {task.title}</span><select value={task.status} disabled={busy} onChange={e => void move(task, e.target.value as Task['status'])}>{(['todo','doing','done'] as const).map(s => <option key={s} value={s}>{statusNames[s]}</option>)}</select></label></article>; })}{filtered.filter(t => t.status === status).length === 0 && <div className="empty-column">{status === 'done' ? 'Hier landen eure Erfolge.' : status === 'doing' ? 'Bereit für euren nächsten Flow.' : 'Platz für den nächsten Schritt.'}</div>}</section>)}</div></>;
}
function Times({ data, userId, manager, range, workspace, setModal, service, run, busy }: { data: Dataset; userId: string; manager: boolean; range: { from: string; to: string }; workspace: Workspace; setModal: (m: Modal) => void; service: Service; run: Run; busy: boolean }) {
  const [scope, setScope] = useState('own'); const [status, setStatus] = useState('all'); const [project, setProject] = useState('all'); const filtered = data.entries.filter(e => (scope === 'team' || e.user_id === userId) && (status === 'all' || e.status === status) && (project === 'all' || e.project_id === project)); const drafts = data.entries.filter(e => e.user_id === userId && e.status === 'draft');
  return <><div className="list-toolbar times-toolbar"><div className="filter-group">{manager && <div className="segmented"><button aria-pressed={scope === 'own'} className={scope === 'own' ? 'selected' : ''} onClick={() => setScope('own')}>Meine Zeiten</button><button aria-pressed={scope === 'team'} className={scope === 'team' ? 'selected' : ''} onClick={() => setScope('team')}>Teamzeiten</button></div>}<label><span className="sr-only">Zeitstatus filtern</span><select value={status} onChange={e => setStatus(e.target.value)}><option value="all">Alle Status</option><option value="draft">Entwurf</option><option value="submitted">Eingereicht</option><option value="approved">Freigegeben</option></select></label><label><span className="sr-only">Projekt filtern</span><select value={project} onChange={e => setProject(e.target.value)}><option value="all">Alle Projekte</option>{data.projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label></div><button className="button secondary small" disabled={!filtered.length} onClick={() => downloadCsv(entriesCsv(filtered, data.projects, data.members), `vave-log-zeiten-${range.from}-${range.to}.csv`)}><ArrowDownToLine size={16}/> CSV</button></div><section className="panel table-panel"><div className="table-summary"><span><strong>{filtered.length}</strong> Zeiteinträge</span><strong>{minutesLabel(sum(filtered))}</strong></div>{filtered.length === 0 ? <Empty title="Zeit für einen Anfang." text="Für diesen Zeitraum und diese Filter gibt es noch keine Zeiten."/> : <div className="table-scroll"><table><thead><tr><th>Datum / Person</th><th>Projekt / Beschreibung</th><th>Dauer</th><th>Status</th><th><span className="sr-only">Aktionen</span></th></tr></thead><tbody>{filtered.map(entry => { const p = data.projects.find(p => p.id === entry.project_id); const member = data.members.find(m => m.user_id === entry.user_id); return <tr key={entry.id}><td><strong>{longDate(entry.work_date)}</strong><small>{member?.display_name || member?.email || 'Teammitglied'}</small></td><td><div className="table-project"><span className="color-dot" style={{ backgroundColor: p?.color }}/><strong>{p?.name || 'Projekt'}</strong></div><small className="entry-note">{entry.note || 'Keine Beschreibung'}</small>{entry.billable && <span className="billable-tag">Abrechenbar</span>}</td><td className="nowrap"><strong>{minutesLabel(entry.minutes)}</strong></td><td><Status value={entry.status}/></td><td><div className="row-actions">{entry.user_id === userId && entry.status === 'draft' && <><button className="icon-button" aria-label={`Zeit vom ${entry.work_date} bearbeiten`} disabled={busy} onClick={() => setModal({ type: 'entry', item: entry })}><Pencil size={16}/></button><button className="icon-button delete-button" aria-label={`Zeit vom ${entry.work_date} löschen`} disabled={busy} onClick={() => setModal({ type: 'confirm', title: 'Zeiteintrag löschen?', text: `${minutesLabel(entry.minutes)} vom ${longDate(entry.work_date)} werden dauerhaft gelöscht.`, label: 'Eintrag löschen', action: () => service.deleteEntry(entry.id) })}><Trash2 size={16}/></button></>}{manager && entry.status === 'submitted' && <><button className="icon-button approve-button" aria-label={`Zeit von ${member?.display_name || 'Teammitglied'} freigeben`} title="Freigeben" disabled={busy} onClick={() => void run(() => service.reviewEntry({ id: entry.id, approve: true }), 'Zeiteintrag freigegeben.')}><Check size={18}/></button><button className="icon-button delete-button" aria-label="Zur Überarbeitung zurückgeben" title="Zur Überarbeitung zurückgeben" disabled={busy} onClick={() => setModal({ type: 'confirm', title: 'Zeit zurückgeben?', text: 'Der Eintrag wird wieder zum Entwurf. Die Person kann ihn korrigieren und erneut einreichen.', label: 'Zurückgeben', action: () => service.reviewEntry({ id: entry.id, approve: false }) })}><X size={18}/></button></>}{(entry.status === 'approved' || (entry.status === 'submitted' && !manager)) && <ShieldCheck size={16} className="muted" aria-label="Eintrag ist gesperrt"/>}</div></td></tr>; })}</tbody></table></div>}</section>{drafts.length > 0 && <div className="submit-strip"><div><CheckCheck size={25}/><div><strong>Alles richtig erfasst?</strong><p>{drafts.length} deiner Entwürfe · {minutesLabel(sum(drafts))} im gesamten gewählten Zeitraum.</p></div></div><button className="button primary" disabled={busy} onClick={() => setModal({ type: 'confirm', title: 'Zeiten einreichen?', text: `Alle ${drafts.length} eigenen Entwürfe vom ${shortDate(range.from)} bis ${shortDate(range.to)} (${minutesLabel(sum(drafts))}) werden zur Prüfung eingereicht – unabhängig von den angezeigten Filtern. Danach sind sie für dich gesperrt, bis die Leitung sie zurückgibt.`, label: 'Zeiten einreichen', action: () => service.submitEntries({ workspace_id: workspace.id, from: range.from, to: range.to }) })}>Zeiten einreichen <ArrowRight size={17}/></button></div>}</>;
}
function Reports({ data, range, manager }: { data: Dataset; range: { from: string; to: string }; manager: boolean }) {
  const [project, setProject] = useState('all'); const [person, setPerson] = useState('all'); const [status, setStatus] = useState('all'); const entries = data.entries.filter(e => (project === 'all' || e.project_id === project) && (person === 'all' || e.user_id === person) && (status === 'all' || e.status === status)); const total = sum(entries); const billable = sum(entries.filter(e => e.billable));
  return <><div className="list-toolbar"><div className="filter-group"><label className="inline-field"><span>Projekt</span><select value={project} onChange={e => setProject(e.target.value)}><option value="all">Alle Projekte</option>{data.projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>{manager && <label className="inline-field"><span>Person</span><select value={person} onChange={e => setPerson(e.target.value)}><option value="all">Ganzes Team</option>{data.members.map(m => <option key={m.user_id} value={m.user_id}>{m.display_name || m.email}</option>)}</select></label>}<label className="inline-field"><span>Status</span><select value={status} onChange={e => setStatus(e.target.value)}><option value="all">Alle Status</option><option value="draft">Entwurf</option><option value="submitted">Eingereicht</option><option value="approved">Freigegeben</option></select></label></div><button className="button secondary small" disabled={!entries.length} onClick={() => downloadCsv(entriesCsv(entries, data.projects, data.members), `vave-log-auswertung-${range.from}-${range.to}.csv`)}><ArrowDownToLine size={16}/> CSV exportieren</button></div><div className="metric-grid report-metrics"><Metric label={manager ? 'Erfasste Teamzeit' : 'Deine erfasste Zeit'} value={minutesLabel(total)} sub={`${entries.length} Einträge nach Filter`} icon={<Clock3 size={19}/>} featured/><Metric label="Abrechenbar" value={minutesLabel(billable)} sub={total ? `${Math.round(billable / total * 100)} % der erfassten Zeit` : 'Noch keine Zeiten'} icon={<Activity size={19}/>}/><Metric label="Freigegebene Zeit" value={minutesLabel(sum(entries.filter(e => e.status === 'approved')))} sub="Bereit zur weiteren Verarbeitung" icon={<ShieldCheck size={19}/>}/></div><section className="panel"><div className="panel-heading"><div><p className="eyebrow">PROJEKTBUDGETS</p><h2>Wo eure Zeit hinfließt.</h2><p>Erfasste Zeit nach Filter im Verhältnis zum gesamten Projektbudget.</p></div></div><Notice kind="info">Die Auswertung zeigt ausschließlich den gewählten Zeitraum{manager ? '' : ' und deine eigenen Zeiten'}. Zeiten außerhalb davon sind nicht enthalten. Ein verbleibendes Gesamtbudget lässt sich daraus nicht ableiten.</Notice>{!data.projects.length ? <Empty title="Noch keine Projekte." text="Sobald Projekte und Zeiten vorhanden sind, erscheint hier eure Auswertung."/> : <div className="budget-list">{data.projects.filter(p => project === 'all' || p.id === project).map(p => { const used = sum(entries.filter(e => e.project_id === p.id)); const percent = p.budget_minutes ? Math.round(used / p.budget_minutes * 100) : 0; return <div className="budget-row" key={p.id}><ProjectMark project={p}/><div className="budget-name"><strong>{p.name}</strong><small>{p.client || p.code}</small></div><div className="budget-bar"><div className="progress-track"><div style={{ width: `${Math.min(percent,100)}%`, backgroundColor: p.color }}/></div><small>{p.budget_minutes ? `${percent} % des Gesamtbudgets im Zeitraum` : 'Kein Budget festgelegt'}</small></div><div className="budget-total"><strong>{minutesLabel(used)}</strong><small>{p.budget_minutes ? `von ${minutesLabel(p.budget_minutes)}` : 'im Zeitraum'}</small></div></div>; })}</div>}</section>{manager && <section className="panel team-report"><div className="panel-heading"><div><p className="eyebrow">TEAMÜBERSICHT</p><h2>Viele Köpfe. Gemeinsamer Fortschritt.</h2></div></div><div className="member-report-grid">{data.members.filter(m => person === 'all' || person === m.user_id).map(m => <div className="member-report" key={m.user_id}><span className="avatar">{initials(m.display_name || m.email)}</span><div><strong>{m.display_name || m.email}</strong><small>{entries.filter(e => e.user_id === m.user_id).length} Einträge</small></div><strong>{minutesLabel(sum(entries.filter(e => e.user_id === m.user_id)))}</strong></div>)}</div></section>}</>;
}
function Team({ data, userId, role, service, run, busy, workspace, setModal }: { data: Dataset; userId: string; role: Role; service: Service; run: Run; busy: boolean; workspace: Workspace; setModal: (m: Modal) => void }) {
  return <><div className="team-intro"><span className="large-number">{String(data.members.length).padStart(2,'0')}</span><div><h2>Menschen. Ein Workspace.</h2><p>Jede Person bringt etwas mit. Zusammen wird etwas draus.</p></div><Users size={44}/></div><section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Person</th><th>E-Mail-Adresse</th><th>Rolle</th></tr></thead><tbody>{data.members.map(member => <tr key={member.user_id}><td><div className="person-cell"><span className="avatar">{initials(member.display_name || member.email)}</span><strong>{member.display_name || 'Teammitglied'}{member.user_id === userId && <span className="you-label">Du</span>}</strong></div></td><td>{member.email}</td><td>{role === 'owner' ? <label><span className="sr-only">Rolle von {member.display_name || member.email}</span><select disabled={busy} value={member.role} onChange={e => { const next = e.target.value as Role; setModal({ type: 'confirm', title: 'Rolle ändern?', text: `${member.display_name || member.email} erhält die Rolle „${roleNames[next]}“.${next === 'disabled' ? ' Der Workspace-Zugriff wird entzogen. Ein laufender Timer wird ohne Zeitbuchung verworfen. Historische Zeiten bleiben erhalten.' : ''}${member.user_id === userId ? ' Dadurch können sich deine eigenen Zugriffsrechte ändern.' : ''}`, label: 'Rolle ändern', action: () => service.setMemberRole({ workspace_id: workspace.id, user_id: member.user_id, role: next }) }); }}>{(['member','manager','owner','disabled'] as Role[]).map(r => <option key={r} value={r}>{roleNames[r]}</option>)}</select></label> : <span className={`role-badge role-${member.role}`}>{roleNames[member.role]}</span>}</td></tr>)}</tbody></table></div></section><div className="role-guide"><div><ShieldCheck size={20}/><h3>Inhaber:in</h3><p>Verwaltet Einladungen und Rollen sowie Projekte und Teamzeiten.</p></div><div><FolderKanban size={20}/><h3>Leitung</h3><p>Verwaltet Projekte, sieht Teamzeiten und prüft eingereichte Zeiten.</p></div><div><Users size={20}/><h3>Mitglied</h3><p>Arbeitet an gemeinsamen Aufgaben und erfasst eigene Zeiten.</p></div></div></>;
}
function Settings({ workspace, self, client, config, signOut }: { workspace: Workspace; self?: Membership; client: SupabaseClient; config: RuntimeConfig; signOut: () => Promise<void> }) {
  const [copy, setCopy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function reset() { if (!self?.email) return; setBusy(true); setMessage(''); setError(''); try { const { error } = await client.auth.resetPasswordForEmail(self.email, { redirectTo: new URL('/?reset=1', config.appUrl).href }); if (error) throw error; setMessage('Der Link zum Zurücksetzen wurde angefordert. Prüfe dein E-Mail-Postfach.'); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <div className="settings-grid"><section className="panel"><div className="panel-heading"><div><p className="eyebrow">DEIN ARBEITSORT</p><h2>{workspace.name}</h2></div><span className="workspace-avatar">{initials(workspace.name)}</span></div><dl className="detail-list"><div><dt>Zeitzone</dt><dd>{workspace.timezone}</dd></div><div><dt>Währung</dt><dd>{workspace.currency}</dd></div><div><dt>Deine Rolle</dt><dd>{roleNames[self?.role || 'member']}</dd></div><div><dt>Workspace-ID</dt><dd className="mono tiny">{workspace.id}</dd></div></dl><p className="tiny muted">Zeitzone und Währung werden beim Anlegen festgelegt. Die Zeitzone bestimmt die Tagesgrenzen deiner Timer.</p></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">DEIN ACCOUNT</p><h2>{self?.display_name || 'Dein Profil'}</h2></div><span className="avatar">{initials(self?.display_name || self?.email || 'Du')}</span></div><dl className="detail-list"><div><dt>E-Mail</dt><dd>{self?.email}</dd></div><div><dt>Anmeldung</dt><dd><span className="verified"><Check size={14}/> Bestätigte E-Mail</span></dd></div></dl>{error && <Notice>{error}</Notice>}{message && <Notice kind="success">{message}</Notice>}<div className="button-row"><button className="button secondary small" disabled={busy} onClick={() => void reset()}>Passwort zurücksetzen</button><button className="button secondary small" onClick={() => void signOut()}><LogOut size={15}/> Abmelden</button></div></section><ConnectedApps client={client}/><section className="panel integration-panel"><span className="integration-symbol" aria-hidden="true">↗</span><p className="eyebrow">DEIN WORKFLOW GEHT WEITER</p><h2>VAVE.LOG für deine Tools.</h2><p className="muted">Verbinde einen MCP-fähigen Client über OAuth. Der Zugriff erfolgt mit deinen Rechten und deiner ausdrücklichen Zustimmung.</p><Field label="MCP-Adresse"><div className="copy-field"><code>{new URL('/api/mcp', config.appUrl).href}</code><button className="icon-button" aria-label="MCP-Adresse kopieren" onClick={() => { void navigator.clipboard.writeText(new URL('/api/mcp', config.appUrl).href).then(() => setCopy(true)).catch(() => setError('Kopieren nicht möglich. Bitte markiere die Adresse manuell.')); }}>{copy ? <Check size={17}/> : <Copy size={17}/>}</button></div></Field>{copy && <span role="status" className="tiny">Adresse kopiert.</span>}<p className="tiny muted">Der Supabase OAuth-Server und der Client müssen für diese Verbindung eingerichtet sein. Details stehen in der Betriebsanleitung.</p></section></div>;
}
function Editor({ modal, data, workspace, service, run, busy, onClose, appUrl, errorDetail }: { modal: Modal; data: Dataset; workspace: Workspace; service: Service; run: Run; busy: boolean; onClose: () => void; appUrl: string; errorDetail?: string }) {
  const id = useRef(('item' in modal ? modal.item?.id : undefined) || crypto.randomUUID()); const [error, setError] = useState(''); const [deleting, setDeleting] = useState(false);
  const item = 'item' in modal ? modal.item : undefined;
  const title = modal.type === 'confirm' ? modal.title : modal.type === 'project' ? (item ? 'Projekt bearbeiten' : 'Neues Projekt') : modal.type === 'task' ? (item ? 'Aufgabe bearbeiten' : 'Neue Aufgabe') : modal.type === 'entry' ? (item ? 'Zeit bearbeiten' : 'Zeit erfassen') : 'Person einladen';
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); setError(''); let action: () => Promise<unknown>;
    if (modal.type === 'confirm') action = modal.action;
    else if (modal.type === 'project') action = () => service.saveProject({ id: id.current, workspace_id: workspace.id, name: String(f.get('name')).trim(), code: String(f.get('code')).trim(), client: String(f.get('client')).trim(), budget_minutes: Math.round(Number(f.get('budget')) * 60), status: String(f.get('status')) as Project['status'], color: String(f.get('color')) });
    else if (modal.type === 'task') action = () => service.saveTask({ id: id.current, workspace_id: workspace.id, project_id: String(f.get('project')), title: String(f.get('title')).trim(), status: String(f.get('status')) as Task['status'], assignee_id: String(f.get('assignee')) || null, due_date: String(f.get('due')) || null });
    else if (modal.type === 'entry') { const minutes = Number(f.get('hours')) * 60 + Number(f.get('minutes')); if (!Number.isInteger(minutes) || minutes < 1 || minutes > 1440) { setError('Bitte erfasse zwischen 1 und 1.440 Minuten.'); return; } action = () => service.saveEntry({ id: id.current, workspace_id: workspace.id, project_id: String(f.get('project')), work_date: String(f.get('date')), minutes, note: String(f.get('note')).trim(), billable: f.get('billable') === 'on' }); }
    else action = () => service.inviteMember({ workspace_id: workspace.id, email: String(f.get('email')).trim(), role: String(f.get('role')) as 'member' | 'manager' });
    const ok = await run(action, modal.type === 'invite' ? 'Einladung hinterlegt. Teile den Website-Link mit der Person; es wurde keine Einladungs-E-Mail verschickt.' : modal.type === 'confirm' ? 'Änderung gespeichert.' : 'Gespeichert.'); if (!ok) setError('Die Änderung wurde nicht bestätigt. Prüfe den Hinweis im Workspace und versuche es erneut.');
  }
  const projectSelect = <Field label="Projekt"><select name="project" required defaultValue={item && 'project_id' in item ? item.project_id : data.projects.find(p => p.status === 'active')?.id || ''}><option value="" disabled>Projekt auswählen</option>{data.projects.filter(p => p.status === 'active' || (item && 'project_id' in item && item.project_id === p.id)).map(p => <option key={p.id} value={p.id}>{p.code} · {p.name}</option>)}</select></Field>;
  return <Dialog title={title} onClose={onClose} busy={busy}><form className="form-stack" onSubmit={submit}>{(errorDetail || error) && <Notice>{errorDetail || error}</Notice>}{modal.type === 'confirm' && <p className="confirm-copy">{modal.text}</p>}{modal.type === 'project' && <><Field label="Projektname"><input name="name" required maxLength={160} defaultValue={modal.item?.name} placeholder="Zum Beispiel: Ein neuer Markenauftritt"/></Field><div className="form-grid"><Field label="Projektcode"><input name="code" required maxLength={24} defaultValue={modal.item?.code} placeholder="VAV-001"/></Field><Field label="Kunde"><input name="client" maxLength={160} defaultValue={modal.item?.client} placeholder="Unternehmen oder Organisation"/></Field></div><div className="form-grid"><Field label="Zeitbudget in Stunden" hint="0 = kein Zeitbudget"><input name="budget" type="number" required min="0" max="100000" step="any" defaultValue={(modal.item?.budget_minutes || 0) / 60}/></Field><Field label="Status"><select name="status" defaultValue={modal.item?.status || 'active'}><option value="active">Aktiv</option><option value="paused">Pausiert</option><option value="archived">Archiviert</option></select></Field></div><Field label="Projektfarbe"><input className="color-input" type="color" name="color" defaultValue={modal.item?.color || '#641dff'}/></Field>{modal.item && <p className="tiny muted">Archivierte Projekte bleiben mit ihren Zeiten und Aufgaben erhalten.</p>}</>}{modal.type === 'task' && <>{projectSelect}<Field label="Aufgabe"><input name="title" required maxLength={240} defaultValue={modal.item?.title} placeholder="Was ist der nächste konkrete Schritt?"/></Field><div className="form-grid"><Field label="Status"><select name="status" defaultValue={modal.item?.status || 'todo'}><option value="todo">Offen</option><option value="doing">In Arbeit</option><option value="done">Erledigt</option></select></Field><Field label="Fällig am"><input name="due" type="date" min="2000-01-01" max="2100-12-31" defaultValue={modal.item?.due_date || ''}/></Field></div><TaskAssigneeSelect members={data.members} currentAssignee={modal.item?.assignee_id}/>{modal.item && (!deleting ? <button type="button" className="text-button danger-text" onClick={() => setDeleting(true)}><Trash2 size={15}/> Aufgabe löschen</button> : <div className="confirm-inline"><p>Diese Aufgabe dauerhaft löschen?</p><div className="button-row"><button className="button danger small" disabled={busy} type="button" onClick={() => void run(() => service.deleteTask(modal.item!.id), 'Aufgabe gelöscht.')}>Ja, löschen</button><button className="text-button" type="button" disabled={busy} onClick={() => setDeleting(false)}>Behalten</button></div></div>)}</>}{modal.type === 'entry' && <>{projectSelect}<Field label="Datum"><input type="date" min="2000-01-01" max="2100-12-31" name="date" required defaultValue={modal.item?.work_date || dateInZone(workspace.timezone)}/></Field><div className="form-grid"><Field label="Stunden"><input type="number" name="hours" min="0" max="24" step="1" required defaultValue={Math.floor((modal.item?.minutes || 0) / 60)}/></Field><Field label="Minuten"><input type="number" name="minutes" min="0" max="59" step="1" required defaultValue={(modal.item?.minutes || 30) % 60}/></Field></div><Field label="Beschreibung"><textarea name="note" rows={3} maxLength={2000} defaultValue={modal.item?.note} placeholder="Woran hast du gearbeitet?"/></Field><label className="checkbox-field"><input type="checkbox" name="billable" defaultChecked={modal.item?.billable ?? true}/> Abrechenbar</label><p className="tiny muted">Die Zeit wird als Entwurf gespeichert. Maximal 24 Stunden pro Tag; Zeitzone {workspace.timezone}.</p></>}{modal.type === 'invite' && <><p className="muted">Hinterlege die E-Mail-Adresse der Person. Die Einladung wird nach ihrer Anmeldung mit bestätigter E-Mail automatisch angenommen.</p><Field label="E-Mail-Adresse"><input name="email" type="email" required maxLength={254} placeholder="person@studio.de" autoComplete="off"/></Field><Field label="Rolle"><select name="role" defaultValue="member"><option value="member">Mitglied</option><option value="manager">Leitung</option></select></Field><Notice kind="info">VAVE.LOG verschickt keine Einladungs-E-Mail. Teile anschließend diesen Website-Link: <span className="wrap-code">{appUrl}</span>. Die Person kann sich dort registrieren.</Notice></>}<FormActions busy={busy} onClose={onClose} label={modal.type === 'confirm' ? modal.label : modal.type === 'invite' ? 'Einladung hinterlegen' : 'Speichern'}/></form></Dialog>;
}
